function attachCarousel(){if(state.page!=='home')return;let change=n=>{state.homeSlide=((state.homeSlide||0)+n+3)%3;render()};app.querySelectorAll('[data-carousel]').forEach(el=>el.onclick=()=>change(Number(el.dataset.carousel)));app.querySelectorAll('[data-carousel-to]').forEach(el=>el.onclick=()=>{state.homeSlide=Number(el.dataset.carouselTo);render()});let carousel=$('[data-home-carousel]');if(carousel){carouselTimer=setInterval(()=>change(1),5000);carousel.onpointerenter=()=>clearInterval(carouselTimer);carousel.onpointerleave=()=>{clearInterval(carouselTimer);carouselTimer=setInterval(()=>change(1),5000)}}}
function go(p){state.page=p;if(p==='rank')state.rankings[state.rank]=null;window.scrollTo(0,0);render()}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
function home(){let slides=[['今日食堂灵感','认真吃饭，也可以很轻松',2],['不知道吃什么？','让转盘替你做决定',111],['发现一份新欢','滑一滑，留下喜欢的菜',376]],i=(state.homeSlide||0)%slides.length,s=slides[i];return `<div class="topline"><div><div class="eyebrow">CAMPUS FOOD CLUB</div><h1>今天吃什么？</h1></div><button class="avatar" data-go="profile" aria-label="个人中心">🍚</button></div><section class="home-carousel sticker" data-home-carousel aria-label="食堂灵感轮播">${photo(d(s[2]).crop,d(s[2]).image)}<span class="hero-label hand">${s[0]}</span><div class="hero-bottom">${s[1]}</div><button class="carousel-arrow prev" data-carousel="-1" aria-label="上一张">‹</button><button class="carousel-arrow next" data-carousel="1" aria-label="下一张">›</button><div class="carousel-dots">${slides.map((_,n)=>`<button class="${n===i?'active':''}" data-carousel-to="${n}" aria-label="第 ${n+1} 张"></button>`).join('')}</div></section>${state.reviews.some(r=>r.dish===1)?'':`<button class="pending" data-open-dish="1"><b>●</b><span><small>待点评</small> 上一餐吃得怎么样？</span><span>›</span></button>`}<div class="section-title"><h2>换个方式决定</h2><span class="hand muted">选一个就出发</span></div><div class="decision-stack"><button class="entry yellow" data-go="roulette"><span class="symbol">◎</span><span><strong>转盘抽窗口</strong><p>交给一点点运气</p></span><span>↗</span></button><button class="entry green" data-go="swipe"><span class="symbol">▱</span><span><strong>滑卡片选菜</strong><p>喜欢就留下，不喜欢就划走</p></span><span>↗</span></button><button class="entry orange" data-go="rank"><span class="symbol">★</span><span><strong>看看排行榜</strong><p>本周和本月的人气菜</p></span><span>↗</span></button></div><div class="section-title"><h2>食堂里有什么</h2><button data-go="catalog">查看全部 ›</button></div>${dishCard(d(2))}${dishCard(d(9))}`}
const _home=home;home=function(){let html=_home(),pending=state.meals.filter(m=>!m.reviewed),first=pending[0],x=first&&d(first.dish),notice=x?`<button class="pending" data-go="pending"><b>●</b><span><small>待评价</small> ${esc(x.name)} 吃得怎么样？</span><span>›</span></button>`:'';return html.replace(/<button class="pending"[\s\S]*?<\/button>/,notice)};
function login(){return `<section class="login-page"><div class="login-mark">🍚</div><div class="eyebrow">CAMPUS FOOD CLUB</div><h1>欢迎来到 AI 助食</h1><p class="subtitle">登录后记录每一顿，找到更适合你的校园美食。</p><div class="card login-card"><label class="form-label" for="login-phone">手机号</label><input id="login-phone" class="input" inputmode="tel" maxlength="20" placeholder="请输入手机号" value="${esc(state.loginPhone||'')}"><label class="form-label" for="login-code">验证码</label><div class="login-code-row"><input id="login-code" class="input" inputmode="numeric" maxlength="6" placeholder="请输入验证码"><button id="send-code" class="pill">获取验证码</button></div><button id="login-submit" class="btn block" style="margin-top:20px">登录并开始选餐</button><p class="login-tip">开发测试验证码：123456</p></div><small class="login-legal">登录即表示同意用户协议与隐私说明</small></section>`}
function dishCard(x){let ww=w(x.win);return `<button class="dish-card card press" data-open-dish="${x.id}"><div class="dish-photo">${photo(x.crop,x.image)}</div><div><strong>${x.name}</strong><small>${cafeterias[ww.c]} · ${ww.name}</small><div class="row" style="margin-top:5px">${stars(x.rating)}<small>(${x.count+reviewCount(x.id)})</small><span class="price">¥${x.price}</span></div><div class="tags">${tag(x.taste||'暂无标签')}</div></div></button>`}
function catalog(){let q=state.query.trim().toLowerCase();let matched=windows.filter(x=>x.c===state.cafeteria&&x.f===state.floor&&(!q||x.name.toLowerCase().includes(q)||cafeterias[x.c].includes(q)||x.d.some(id=>d(id).name.toLowerCase().includes(q))));return `${head('所有菜品')}<label class="search"><span>⌕</span><input id="search" aria-label="搜索菜品、食堂或窗口" placeholder="搜索菜品、食堂或窗口" value="${esc(state.query)}"></label><div class="chips" style="margin-top:14px">${cafeterias.map((c,i)=>`<button class="pill ${i===state.cafeteria?'active':''}" data-cafeteria="${i}">${c}</button>`).join('')}</div><div class="floor-layout"><div class="floors">${[1,2,3].map(n=>`<button class="${state.floor===n?'active':''}" data-floor="${n}">${['','一','二','三'][n]}层</button>`).join('')}</div><div>${matched.length?matched.map(x=>`<button class="window-card press" data-open-window="${x.id}"><strong>${x.name}　›</strong><span class="meta">${x.f} 层 · ${x.d.length} 道菜</span><div class="chips" style="margin-top:10px">${x.d.slice(0,2).map(id=>tag(d(id).name)).join('')}</div></button>`).join(''):`<div class="empty hand">这里没找到，换个词或楼层试试</div>`}</div></div>${q?`<div class="section-title"><h2>相关菜品</h2></div>${dishes.filter(x=>x.name.toLowerCase().includes(q)&&w(x.win).c===state.cafeteria).map(dishCard).join('')||'<p class="muted">暂无匹配菜品</p>'}`:''}`}
function windowPage(){let x=w(state.window);if(!x)return '';let arr=x.d.map(d);if(state.sort==='rating')arr.sort((a,b)=>b.rating-a.rating);if(state.sort==='count')arr.sort((a,b)=>b.count-a.count);if(state.sort==='price')arr.sort((a,b)=>a.price-b.price);if(state.sort==='new')arr.sort((a,b)=>b.id-a.id);return `${head(x.name,'catalog')}<div class="card" style="padding:16px"><b>${cafeterias[x.c]} · ${x.f} 层</b><p class="muted" style="margin-top:5px">${x.d.length} 道菜可选</p></div><div class="sortline">${[['rating','评分优先'],['count','点评人数'],['new','最新'],['price','价格从低到高']].map(([v,t])=>`<button class="pill ${state.sort===v?'active':''}" data-sort="${v}">${t}</button>`).join('')}</div>${arr.map(dishCard).join('')}`}
function reviewCount(id){return state.reviews.filter(x=>x.dish===id).length}
function allReviews(x){return state.reviews.filter(r=>r.dish===x.id).sort((a,b)=>b.time-a.time)}
function detail(){let x=d(state.dish);if(!x)return '';let ww=w(x.win),remote=state.dishRatings[x.id]||[],rr=remote.length?remote:allReviews(x).filter(r=>!r.mine),stats=state.dishStats[x.id]||{},avg=Number(stats.rating_avg??x.rating??0),count=Number(stats.rating_count??x.count??0),eaten=state.meals.some(m=>Number(m.dish)===x.id&&!m.reviewed);return `${head('菜品详情',state.from||'catalog')}<div class="dish-wide">${photo(x.crop,x.image)}</div><div class="card" style="padding:18px;margin-top:-20px;position:relative"><div class="row between"><h1>${x.name}</h1><span class="price" style="font-size:23px">¥${x.price}</span></div><p class="muted" style="margin:5px 0 12px">${cafeterias[ww.c]} · ${ww.f} 层 ${ww.name}</p><div class="row">${stars(avg)}<small>${count} 人评价</small>${tag(x.taste||'暂无标签')}</div></div>${!eaten?`<button class="btn block meal-button" data-record-meal="${x.id}">我要吃这道菜</button>`:`<div class="meal-notice">已记录用餐，可前往“待评价”完成评价</div>`}<div class="section-title"><h2>大家怎么说</h2><small>${count} 条评分</small></div><div class="card" style="padding:16px"><div class="row between"><div><strong style="font-size:31px;color:var(--caramel)">${avg.toFixed(1)}</strong><div class="stars">★★★★★</div></div><div style="flex:1"><p class="meta">评分来自真实用餐评价，人数越多排名越稳定。</p></div></div></div><div class="nutrition"><div class="row between"><h3>营养参考</h3>${tag('估算值','mint')}</div><div class="nutrition-grid">${[['热量',x.kcal==null?'暂无':x.kcal+'kcal'],['蛋白质',x.protein==null?'暂无':x.protein+'g'],['脂肪',x.fat==null?'暂无':x.fat+'g'],['碳水',x.carbs==null?'暂无':x.carbs+'g']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div></div><div class="section-title"><h2>他人评价</h2></div>${rr.length?rr.map(r=>`<div class="review card"><div class="row between"><strong>${esc(r.name||'匿名用户')}</strong><small>${r.time?new Date(r.time).toLocaleDateString('zh-CN'):''}</small></div><div class="stars">${'★'.repeat(Number(r.stars??r.overall_score))}${'☆'.repeat(5-Number(r.stars??r.overall_score))}</div><div>${(r.tags||r.quick_tags||[]).map(t=>tag(t,'red')).join(' ')}</div><p>${esc(r.text??r.comment??'只给了评分')}</p></div>`).join(''):`<div class="review card"><strong>暂无他人评价</strong><p>真实用餐并评价后，会帮助下一位同学做决定。</p></div>`}`}
function rank(){let rows=state.rankings[state.rank];return `${head('人气排行榜')}<p class="subtitle">根据本周期真实评价计算，采用评分与评价人数的贝叶斯加权。</p><div class="chips" style="margin-bottom:18px"><button class="pill ${state.rank==='week'?'active':''}" data-rank="week">本周榜</button><button class="pill ${state.rank==='month'?'active':''}" data-rank="month">本月榜</button></div>${rows===null?'<div class="empty hand">正在加载真实榜单…</div>':rows.length?rows.map((r,i)=>`<button class="rank-item card ${i<3?'top'+(i+1):''}" data-open-dish="${r.id}"><span class="rank-num">${i===0?'🥇':i===1?'🥈':i===2?'🥉':String(i+1).padStart(2,'0')}</span><span class="rank-copy"><strong>${esc(r.name)}</strong><small>${esc(r.cafeteria_name||'')} · ${esc(r.window_name||'')}</small></span><span class="rank-score">★ ${Number(r.rating_avg).toFixed(2)}<small style="display:block">${r.rating_count} 人评价</small></span></button>`).join(''):'<div class="empty hand">本周期还没有真实评价，榜单将在有人用餐并评价后生成。</div>'}`}
function roulette(){let r=state.roulette;if(r.c===null)return `${head('转盘抽窗口')}<p class="subtitle">先选一个食堂，转盘会从它的全部窗口中抽出今天的目的地。</p><div class="cafeteria-picker">${cafeterias.map((c,i)=>`<button class="choice-card press ${i?'mint-choice':'butter-choice'}" data-roulette-c="${i}"><span class="choice-icon">${i?'♨':'◎'}</span><strong>${c}</strong><small>从全部窗口里抽取</small><span class="choice-arrow">→</span></button>`).join('')}</div>`;let pool=windows.filter(x=>x.c===r.c),remaining=pool.filter(x=>!r.drawn.includes(x.id)),result=w(r.result),slice=360/pool.length,stops=pool.map((_,n)=>`${n%2?'var(--pudding)':'var(--butter)'} ${n*slice}deg ${(n+1)*slice}deg`).join(',');return `${head('转盘抽窗口')}<div class="roulette-toolbar"><span class="pill active">${cafeterias[r.c]}</span><button class="back" data-roulette-reset="1" ${r.spinning?'disabled':''}>换食堂</button></div><div class="roulette-status"><span>已抽 <b>${r.drawn.length}</b> / ${pool.length}</span><span>剩余 <b>${remaining.length}</b> 个窗口</span></div><div class="wheel-wrap"><div class="wheel-pointer" aria-hidden="true"></div><div class="wheel ${r.spinning?'is-spinning':''}" style="background:conic-gradient(${stops});transform:rotate(${r.rotation||0}deg)" role="img" aria-label="${r.spinning?'正在抽取窗口':cafeterias[r.c]+'窗口转盘'}">${pool.map((x,n)=>`<span class="wheel-label" style="transform:rotate(${n*slice+slice/2}deg) translateY(calc(var(--wheel-size) * -.35))">${x.name.slice(0,5)}</span>`).join('')}<div class="wheel-center">${r.spinning?'正在<br>摇一摇':'今天<br>吃这里'}</div></div></div>${r.spinning?`<p class="wheel-loading hand">正在摇窗口...</p>`:result?`<section class="spin-result sticker"><span class="hand">好耶，抽到了！</span><h2>${result.name}</h2><p>${cafeterias[result.c]} · ${result.f} 层</p><button class="btn block" data-open-window="${result.id}">查看窗口菜品</button></section>`:''}<button class="btn block spin-cta" id="draw" ${r.spinning?'disabled':''}>${r.spinning?'转盘转动中...':remaining.length?(result?'再转一次':'启动转盘'):'本轮抽完，重新开始'}</button><p class="meta roulette-note">抽取范围：${cafeterias[r.c]}的全部窗口</p>`}
function swipe(){let s=state.swipe;if(s.c===null)return `${head('滑卡片选菜')}<p class="subtitle">右滑留下喜欢的菜，左滑跳过。先选一个食堂开始吧。</p><div class="cafeteria-picker">${cafeterias.map((c,i)=>`<button class="choice-card press ${i?'mint-choice':'butter-choice'}" data-swipe-c="${i}"><span class="choice-icon">▱</span><strong>${c}</strong><small>开始挑选今天想吃的菜</small><span class="choice-arrow">→</span></button>`).join('')}</div>`;let cur=d(s.deck[s.index]);if(s.list||!cur)return `${head(s.round===2?'第二轮结果':'喜欢清单')}<div class="roulette-toolbar"><span class="pill active">${cafeterias[s.c]}</span><button class="back" data-swipe-reset="1">重新开始</button></div><div class="swipe-list-intro"><span class="hand">${s.round===2?'筛选完成！':'你的选择'}</span><h2>${s.liked.length?`留下了 ${s.liked.length} 道菜`:'还没有留下菜品'}</h2><p>${s.liked.length?'点开菜品查看详情，或继续筛选。':'再试一轮，找到今天想吃的。'}</p></div>${s.liked.map(id=>`<button class="list-item card" data-open-dish="${id}"><span><strong>${d(id).name}</strong><small>${w(d(id).win).name}</small></span><span class="price">¥${d(id).price} ›</span></button>`).join('')}${s.index<s.deck.length?`<button class="btn block" data-swipe-continue="1">继续挑选</button>`:''}${s.round===1&&s.liked.length>6?`<button class="btn light block" id="second-round">喜欢太多？再筛一轮</button>`:''}<button class="btn secondary block" data-swipe-reset="1">重新开始</button>`;let rem=s.deck.length-s.index;return `${head(s.round===2?'再筛一轮':'滑卡片选菜')}<div class="swipe-toolbar"><span class="pill active">${cafeterias[s.c]}</span><button class="back" data-swipe-list="1">喜欢清单 (${s.liked.length})</button></div><div class="swipe-count"><span>已选 <b>${s.liked.length}</b> 道</span><span>剩余 <b>${rem}</b> 道</span></div><div class="progress"><i style="width:${Math.round(s.index/s.deck.length*100)}%"></i></div><div class="swipe-stage"><div class="swipe-hint skip">跳过</div><div class="swipe-hint like">喜欢</div><div class="swipe-card" id="swipe-card">${photo(cur.crop,cur.image)}<div class="swipe-info"><div class="row between"><h2>${cur.name}</h2><span class="price">¥${cur.price}</span></div><p class="muted">${w(cur.win).name} · ${stars(cur.rating)}</p><div class="tags">${tag(cur.taste||'暂无标签')}</div></div></div></div><div class="swipe-actions"><button class="swipe-action skip-action" data-swipe-action="skip" aria-label="跳过">×<small>跳过</small></button><button class="swipe-action undo-action" data-swipe-undo="1" ${s.history.length?'':'disabled'} aria-label="撤销上一步">↶</button><button class="swipe-action like-action" data-swipe-action="like" aria-label="喜欢">♥<small>喜欢</small></button></div><p class="meta swipe-help">向左滑跳过，向右滑喜欢</p>`}
function ai(){return `${head('AI 助手')}<div class="ai-entry"><div class="row between"><h2>✦ 饮食小助手</h2>${tag('演示模式','mint')}</div><p style="margin-top:8px;line-height:1.6">输入今天吃的菜，试试营养估算。可上传照片记录，但照片识别需要接入 AI 服务。</p></div><div class="chips"><button class="chip" data-ai-prompt="我今天吃了番茄炒蛋和宫保鸡丁">分析今日饮食</button><button class="chip" data-ai-prompt="减脂期间食堂怎么选？">减脂怎么选</button></div><div class="chat" id="chat"><div class="bubble ai">你好！告诉我今天吃了什么，我会用示例菜品数据做一份营养估算。</div>${state.messages.map(m=>`<div class="bubble ${m.role}">${m.html||esc(m.text)}</div>`).join('')}</div><div class="ai-compose"><textarea id="ai-input" class="textarea" aria-label="输入饮食问题" placeholder="例如：我今天吃了番茄炒蛋和宫保鸡丁">${esc(state.aiInput)}</textarea><button id="ai-send" class="btn small">发送</button></div><div class="row between" style="margin-top:10px"><label class="pill" for="ai-photo">＋ 上传餐食照片</label><input type="file" id="ai-photo" accept="image/*" style="display:none"><small>${state.photoName?esc(state.photoName):'AI 建议仅供参考'}</small></div>`}
function profile(){return `${head('个人中心')}<div class="profile-head"><div class="avatar">🍽</div><div><h2>${esc(state.nickname)}</h2><p class="muted" style="margin-top:4px">${esc(state.userId?'已登录':'未登录')}</p></div></div><button class="btn secondary block logout-button" id="logout">退出登录</button><div class="section-title"><h2>我的偏好</h2><button data-go="prefs">编辑 ›</button></div><div class="card" style="padding:16px"><div class="chips">${[...state.preferences.taste,...state.preferences.dislike.map(x=>'忌 '+x),state.preferences.goal].map(x=>tag(x)).join('')||'<span class="muted">还没有设置偏好</span>'}</div><p class="meta" style="margin-top:13px">偏好仅保存在个人资料，不影响转盘和卡片抽取。</p></div><div class="section-title"><h2>我的点评</h2><small>${state.reviews.length} 条</small></div>${state.reviews.length?state.reviews.slice().sort((a,b)=>b.time-a.time).map((r,i)=>`<div class="review card"><div class="row between"><button class="back" data-open-dish="${r.dish}">${d(r.dish).name} ›</button><button class="back" data-delete-review="${r.time}" aria-label="删除点评" style="color:var(--tomato)">删除</button></div><div class="stars">${'★'.repeat(r.stars)}</div><p>${esc(r.text||'只给了评分')}</p></div>`).join(''):'<div class="empty hand">还没有点评，去给喜欢的菜打个分吧</div>'}`}
function pendingReviews(){let items=state.meals.filter(m=>!m.reviewed);return `${head('待评价','profile')}<p class="subtitle">只有记录过实际用餐的菜品，才可以提交评价。</p>${items.length?items.map(m=>{let x=d(m.dish);return x?`<button class="pending-review-card card" data-start-review="${m.id}"><span>${photo(x.crop,x.image)}</span><span><strong>${x.name}</strong><small>用餐记录 · ${new Date(m.time||Date.now()).toLocaleDateString('zh-CN')}</small></span><b>去评价 ›</b></button>`:''}).join(''):'<div class="empty hand">暂无待评价用餐记录</div>'}`}
function reviewPage(){let m=state.meals.find(x=>String(x.id)===String(state.reviewMeal));let x=m&&d(m.dish);if(!m||!x)return `${head('待评价','profile')}<div class="empty">找不到用餐记录</div>`;return `${head('评价这道菜','pending')}<div class="card review-editor"><div class="row"><div class="review-thumb">${photo(x.crop,x.image)}</div><div><h2>${x.name}</h2><p class="muted">确认你已经吃过后再提交评价</p></div></div><label class="form-label">整体评分</label><div class="review-stars">${[1,2,3,4,5].map(n=>`<button data-star="${n}" class="${n<=state.reviewStars?'active':''}" aria-label="${n} 星">★</button>`).join('')}</div><label class="form-label">快速标签</label><div class="chips">${['好吃','分量足','很新鲜','性价比高','下次还吃'].map(t=>`<button class="chip ${state.reviewTags.includes(t)?'active':''}" data-review-tag="${t}">${t}</button>`).join('')}</div><textarea id="review-text" class="textarea" maxlength="200" placeholder="说说真实感受（可选）">${esc(state.reviewText||'')}</textarea><button id="submit-meal-review" class="btn block">提交评价</button></div>`}
function shuffleDiversely(list){let a=[...list];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}for(let i=1;i<a.length;i++){let prev=d(a[i-1]),cur=d(a[i]);if(prev&&cur&&w(prev.win)?.id===w(cur.win)?.id){let j=i+1;while(j<a.length&&w(d(a[j])?.win)?.id===w(prev.win)?.id)j++;if(j<a.length)[a[i],a[j]]=[a[j],a[i]]}}return a}
function sourceName(){return ({swipe:'swipe',roulette:'roulette',window:'catalog',catalog:'catalog',home:'home'})[state.from]||'catalog'}
async function recordMeal(id){let x=d(id);if(!x)return;let local=state.meals.find(m=>Number(m.dish)===Number(id)&&!m.reviewed);if(local){toast('这道菜已有待评价记录');go('pending');return}let meal={id:`local-${Date.now()}`,dish:Number(id),reviewed:false,time:Date.now(),source:sourceName()};state.meals.unshift(meal);persist();render();toast('已记录用餐，可在待评价中完成评价');if(state.userId){try{let res=await fetch(`${API_BASE}/api/users/${state.userId}/meals`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:Number(state.userId),dish_id:Number(id),source:meal.source})});let data=await res.json();if(res.ok){meal.id=data.id;meal.time=Date.now();persist();}}catch(e){console.warn('meal sync failed',e)}}}
async function loadRankings(period){if(state.loadingRank===period)return;state.loadingRank=period;try{let r=await fetch(`${API_BASE}/api/rankings?period=${period}`);if(!r.ok)throw Error();state.rankings[period]=await r.json();persist();if(state.page==='rank')render()}catch(e){state.rankings[period]=[];if(state.page==='rank')render()}finally{state.loadingRank=null}}
async function loadDishData(id){if(state.loadingDish[id]||state.dishStats[id]&&state.dishRatings[id])return;state.loadingDish[id]=true;try{let [a,b]=await Promise.all([fetch(`${API_BASE}/api/dishes/${id}`),fetch(`${API_BASE}/api/dishes/${id}/ratings`)]);if(a.ok)state.dishStats[id]=await a.json();if(b.ok){let rows=await b.json();state.dishRatings[id]=rows.map(r=>({name:r.nickname,overall_score:r.overall_score,comment:r.comment,quick_tags:r.quick_tags,time:r.created_at}))}persist()}catch(e){console.warn('dish sync failed',e)}finally{delete state.loadingDish[id];if(state.page==='detail'&&Number(state.dish)===Number(id))render()}}
function attachExtras(){app.querySelectorAll('[data-record-meal]').forEach(el=>el.onclick=()=>recordMeal(Number(el.dataset.recordMeal)));app.querySelectorAll('[data-go="pending-reviews"]').forEach(el=>el.onclick=()=>go('pending'));app.querySelectorAll('[data-start-review]').forEach(el=>el.onclick=()=>{state.reviewMeal=el.dataset.startReview;state.reviewStars=0;state.reviewTags=[];state.reviewText='';go('review')});let submit=$('#submit-meal-review');if(submit)submit.onclick=async()=>{let m=state.meals.find(x=>String(x.id)===String(state.reviewMeal));if(!m||!state.reviewStars){toast(!m?'用餐记录不存在':'请先选择星级');return}let text=$('#review-text').value.trim();if(state.userId&&!String(m.id).startsWith('local-')){try{let r=await fetch(`${API_BASE}/api/dishes/${m.dish}/ratings`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:Number(state.userId),meal_id:Number(m.id),overall_score:state.reviewStars,taste_score:state.reviewStars,value_score:state.reviewStars,comment:text||null,quick_tags:state.reviewTags})});if(!r.ok){let e=await r.json().catch(()=>({}));toast(e.detail||'评价提交失败');return}}catch(e){toast('网络异常，评价未提交');return}}state.reviews.unshift({dish:m.dish,name:state.nickname,stars:state.reviewStars,tags:[...state.reviewTags],text,time:Date.now(),mine:true});m.reviewed=true;persist();state.reviewMeal=null;toast('评价已提交');go('profile')};if(state.page==='rank'&&state.rankings[state.rank]===null)loadRankings(state.rank);if(state.page==='detail'){loadDishData(state.dish)}if(state.page==='profile'){let n=state.meals.filter(m=>!m.reviewed).length;app.querySelectorAll('[data-pending-count]').forEach(el=>el.textContent=n)}}
function prefs(){let p=state.preferences;return `${head('偏好设置','profile')}<p class="subtitle">这些标签保存在你的资料中，选餐抽取不会用它们过滤菜品。</p><label class="form-label">口味偏好（最多 5 个）</label><div class="chips">${['辣','酸','甜','咸','清淡'].map(x=>`<button class="chip ${p.taste.includes(x)?'active':''}" data-pref-taste="${x}">${x}</button>`).join('')}</div><label class="form-label">忌口</label><div class="chips">${['香菜','葱','姜','蒜','海鲜','花生'].map(x=>`<button class="chip ${p.dislike.includes(x)?'active':''}" data-pref-dislike="${x}">${x}</button>`).join('')}</div><label class="form-label">饮食目标</label><div class="chips">${['维持','减脂','增肌'].map(x=>`<button class="chip ${p.goal===x?'active':''}" data-pref-goal="${x}">${x}</button>`).join('')}</div><label class="form-label" for="allergy">过敏食材</label><input class="input" id="allergy" value="${esc(p.allergy)}" placeholder="例如：花生、虾"><button class="btn block" style="margin-top:20px" id="save-prefs">保存偏好</button>`}
function openDish(id){state.from=state.page;state.dish=Number(id);state.reviewStars=0;state.reviewTags=[];state.reviewText='';go('detail')}
function openWindow(id){state.window=Number(id);go('window')}
function swipeAction(action){let s=state.swipe,id=s.deck[s.index];if(!id)return;s.history.push({id,action});if(action==='like')s.liked.push(id);else if(s.round===2)s.liked=s.liked.filter(x=>x!==id);s.index++;render()}
function animateSwipe(action){if(swipeAnimating)return;let card=$('#swipe-card');if(!card){swipeAction(action);return}swipeAnimating=true;card.classList.add(action==='like'?'fly-like':'fly-skip');setTimeout(()=>{swipeAnimating=false;swipeAction(action)},220)}
function analyzeAI(txt){let matched=dishes.filter(x=>txt.includes(x.name));if(matched.length){let sums={kcal:0,protein:0,fat:0,carbs:0};matched.forEach(x=>Object.keys(sums).forEach(k=>sums[k]+=x[k]));let pct=Math.min(100,Math.round(sums.kcal/2000*100));return `<strong>今日饮食估算</strong><br>识别到：${matched.map(x=>x.name).join('、')}<div class="nutrition" style="margin:10px 0 0;background:#e1f4eb"><b>${sums.kcal} kcal</b> / 2000 kcal<div class="progress"><i style="width:${pct}%"></i></div><div class="nutrition-grid"><div><small>蛋白质</small><b>${sums.protein}g</b></div><div><small>脂肪</small><b>${sums.fat}g</b></div><div><small>碳水</small><b>${sums.carbs}g</b></div><div><small>占日参考</small><b>${pct}%</b></div></div></div><span style="font-size:12px">按示例菜品营养数据相加，份量不同会影响结果。建议搭配蔬菜和足量饮水，仅供参考。</span>`}return '我暂时只能分析页面里收录的菜品。试试输入“我今天吃了番茄炒蛋和宫保鸡丁”。一般选餐可搭配主食、蛋白质和蔬菜，建议仅供参考。'}
function sendAI(){let box=$('#ai-input'),txt=box.value.trim();if(!txt)return;state.messages.push({role:'user',text:txt},{role:'ai',html:analyzeAI(txt)});state.aiInput='';render();setTimeout(()=>$('#chat')?.scrollIntoView({block:'end',behavior:'smooth'}),0)}
let searchTimer;
function attach(){app.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));app.querySelectorAll('[data-open-dish]').forEach(el=>el.onclick=()=>openDish(el.dataset.openDish));app.querySelectorAll('[data-open-window]').forEach(el=>el.onclick=()=>openWindow(el.dataset.openWindow));app.querySelectorAll('[data-cafeteria]').forEach(el=>el.onclick=()=>{state.cafeteria=Number(el.dataset.cafeteria);render()});app.querySelectorAll('[data-floor]').forEach(el=>el.onclick=()=>{state.floor=Number(el.dataset.floor);render()});app.querySelectorAll('[data-sort]').forEach(el=>el.onclick=()=>{state.sort=el.dataset.sort;render()});app.querySelectorAll('[data-rank]').forEach(el=>el.onclick=()=>{state.rank=el.dataset.rank;render()});let search=$('#search');if(search)search.oninput=()=>{let v=search.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.query=v;let pos=search.selectionStart;render();$('#search')?.focus();try{$('#search').setSelectionRange(pos,pos)}catch{}},300)};app.querySelectorAll('[data-star]').forEach(el=>el.onclick=()=>{state.reviewStars=Number(el.dataset.star);render();$('#review-text')?.scrollIntoView({block:'nearest'})});app.querySelectorAll('[data-review-tag]').forEach(el=>el.onclick=()=>{let t=el.dataset.reviewTag;state.reviewTags=state.reviewTags.includes(t)?state.reviewTags.filter(x=>x!==t):[...state.reviewTags,t];render()});let submit=$('#submit-review');if(submit)submit.onclick=()=>{if(!state.reviewStars){toast('请先选择星级');return}if(state.reviews.some(r=>r.dish===state.dish&&Date.now()-r.time<86400000)){toast('这道菜 24 小时内已点评');return}state.reviews.push({dish:state.dish,name:state.nickname,stars:state.reviewStars,tags:state.reviewTags,text:$('#review-text').value.trim(),time:Date.now()});persist();state.reviewStars=0;state.reviewTags=[];state.reviewText='';toast('点评已提交');render()};app.querySelectorAll('[data-roulette-c]').forEach(el=>el.onclick=()=>{state.roulette={c:Number(el.dataset.rouletteC),drawn:[],result:null,spins:0};render()});let draw=$('#draw');if(draw)draw.onclick=()=>{let r=state.roulette,pool=windows.filter(x=>x.c===r.c&&!r.drawn.includes(x.id));if(!pool.length){r.drawn=[];r.result=null;render();return}let x=pool[Math.floor(Math.random()*pool.length)];r.drawn.push(x.id);r.result=x.id;r.spins++;render()};app.querySelectorAll('[data-roulette-reset]').forEach(el=>el.onclick=()=>{state.roulette={c:null,drawn:[],result:null,spins:0};render()});app.querySelectorAll('[data-swipe-c]').forEach(el=>el.onclick=()=>{let c=Number(el.dataset.swipeC);state.swipe={c,round:1,deck:dishes.filter(x=>w(x.win).c===c).map(x=>x.id),index:0,liked:[],history:[],list:false};render()});app.querySelectorAll('[data-swipe-action]').forEach(el=>el.onclick=()=>swipeAction(el.dataset.swipeAction));app.querySelectorAll('[data-swipe-undo]').forEach(el=>el.onclick=()=>{let s=state.swipe,last=s.history.pop();if(!last)return;s.index--;if(last.action==='like')s.liked=s.liked.filter(x=>x!==last.id);else if(s.round===2)s.liked.push(last.id);render()});app.querySelectorAll('[data-swipe-list]').forEach(el=>el.onclick=()=>{state.swipe.list=true;render()});app.querySelectorAll('[data-swipe-continue]').forEach(el=>el.onclick=()=>{state.swipe.list=false;render()});app.querySelectorAll('[data-swipe-reset]').forEach(el=>el.onclick=()=>{state.swipe={c:null,round:1,deck:[],index:0,liked:[],history:[],list:false};render()});let second=$('#second-round');if(second)second.onclick=()=>{let s=state.swipe;s.round=2;s.deck=[...s.liked];s.liked=[];s.index=0;s.history=[];s.list=false;render()};app.querySelectorAll('[data-pref-taste]').forEach(el=>el.onclick=()=>{let t=el.dataset.prefTaste,a=state.preferences.taste;if(!a.includes(t)&&a.length>=5){toast('最多选择 5 个口味');return}state.preferences.taste=a.includes(t)?a.filter(x=>x!==t):[...a,t];render()});app.querySelectorAll('[data-pref-dislike]').forEach(el=>el.onclick=()=>{let t=el.dataset.prefDislike,a=state.preferences.dislike;state.preferences.dislike=a.includes(t)?a.filter(x=>x!==t):[...a,t];render()});app.querySelectorAll('[data-pref-goal]').forEach(el=>el.onclick=()=>{state.preferences.goal=el.dataset.prefGoal;render()});let save=$('#save-prefs');if(save)save.onclick=()=>{state.preferences.allergy=$('#allergy').value.trim();persist();toast('偏好已保存');go('profile')};app.querySelectorAll('[data-delete-review]').forEach(el=>el.onclick=()=>{if(confirm('删除这条点评？')){state.reviews=state.reviews.filter(r=>r.time!==Number(el.dataset.deleteReview));persist();render();toast('已删除')}});app.querySelectorAll('[data-ai-prompt]').forEach(el=>el.onclick=()=>{state.aiInput=el.dataset.aiPrompt;render();$('#ai-input')?.focus()});let aiSend=$('#ai-send');if(aiSend)aiSend.onclick=sendAI;let aiInput=$('#ai-input');if(aiInput)aiInput.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAI()}};let photoInput=$('#ai-photo');if(photoInput)photoInput.onchange=()=>{state.photoName=photoInput.files[0]?.name||'';toast('照片已选，识别需接入 AI 服务');render()};attachSwipe()}
function attachSwipe(){let card=$('#swipe-card');if(!card)return;let start=null,hints=app.querySelectorAll('.swipe-hint');let reset=()=>{card.style.transform='';hints.forEach(h=>h.style.opacity='')};card.onpointerdown=e=>{if(start!==null||swipeAnimating)return;start={x:e.clientX,y:e.clientY};card.setPointerCapture(e.pointerId)};card.onpointermove=e=>{if(!start)return;let dx=e.clientX-start.x,amount=Math.min(1,Math.abs(dx)/95);card.style.transform=`translateX(${dx}px) rotate(${dx/25}deg)`;hints.forEach(h=>h.style.opacity=h.classList.contains(dx>0?'like':'skip')?String(.35+amount*.65):'.16')};card.onpointerup=e=>{if(!start)return;let dx=e.clientX-start.x;start=null;if(Math.abs(dx)>80)animateSwipe(dx>0?'like':'skip');else reset()};card.onpointercancel=()=>{start=null;reset()}}
function startRoulette(){let r=state.roulette,pool=windows.filter(x=>x.c===r.c&&!r.drawn.includes(x.id));if(r.spinning)return;if(!pool.length){state.roulette={...r,drawn:[],result:null,spinning:false};render();return}let winner=pool[Math.floor(Math.random()*pool.length)],all=windows.filter(x=>x.c===r.c),slice=360/all.length,index=all.findIndex(x=>x.id===winner.id);r.drawn.push(winner.id);r.result=null;r.spinning=true;r.spins=(r.spins||0)+1;r.rotation=(r.rotation||0)+1800+(360-(index+.5)*slice);render();clearTimeout(rouletteTimer);rouletteTimer=setTimeout(()=>{if(state.page!=='roulette'||state.roulette!==r)return;r.result=winner.id;r.spinning=false;render()},1100)}
app.addEventListener('click',e=>{let draw=e.target.closest('#draw'),action=e.target.closest('[data-swipe-action]');if(draw){e.preventDefault();e.stopPropagation();startRoulette()}if(action){e.preventDefault();e.stopPropagation();animateSwipe(action.dataset.swipeAction)}},true);
document.addEventListener('keydown',e=>{if(state.page==='swipe'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){if(e.key==='ArrowRight')animateSwipe('like');if(e.key==='ArrowLeft')animateSwipe('skip')}});
const _attachExtras=attachExtras;attachExtras=function(){_attachExtras();app.querySelectorAll('[data-swipe-c]').forEach(el=>el.onclick=()=>{let c=Number(el.dataset.swipeC);state.swipe={c,round:1,deck:shuffleDiversely(dishes.filter(x=>w(x.win).c===c)).map(x=>x.id),index:0,liked:[],history:[],list:false};render()});if(state.page==='login'){let send=$('#send-code');if(send)send.onclick=async()=>{let phone=$('#login-phone').value.trim();if(phone.length<6){toast('请输入正确手机号');return}state.loginPhone=phone;try{let r=await fetch(`${API_BASE}/api/auth/send-code`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone})});toast(r.ok?'验证码已发送，开发验证码为 123456':'验证码发送失败')}catch(e){toast('验证码发送失败')}};let submit=$('#login-submit');if(submit)submit.onclick=async()=>{let phone=$('#login-phone').value.trim(),code=$('#login-code').value.trim();if(phone.length<6||!code){toast('请填写手机号和验证码');return}try{let r=await fetch(`${API_BASE}/api/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone,code,nickname:state.nickname})}),data=await r.json();if(!r.ok){toast(data.detail||'登录失败');return}state.authToken=data.token;state.userId=data.user.id;state.nickname=data.user.nickname;state.page='home';persist();toast('登录成功');render()}catch(e){toast('无法连接登录服务')}}}}
const _attachLogout=attachExtras;attachExtras=function(){_attachLogout();let logout=$('#logout');if(logout)logout.onclick=()=>{state.authToken=null;state.userId=null;state.page='login';persist();render()}};
render();


